def sum_divisors(n):
    """Return the sum of all positive divisors of n (n >= 1), including 1 and n."""
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            j = n // i
            if j != i:
                total += j
        i += 1
    return total


def are_equivalent(a, b):
    """Return True if a and b have the same sum of divisors."""
    return sum_divisors(a) == sum_divisors(b)


assert are_equivalent(36, 57) == False
